-- Servicio #1: PETMAX S.A.C. (20610289321) - 2025-12-01

INSERT INTO Servicio (id_sede, id_ruta, id_planta, fecha_programada, fecha_ejecucion, estado, estado_pago, forma_pago)
SELECT 
    se.id_sede,
    (SELECT r.id_ruta FROM Ruta r 
     INNER JOIN Vehiculo v ON r.id_vehiculo = v.id_vehiculo 
     WHERE r.fecha = '2025-12-01' AND v.modelo = 'DONFENG 1' LIMIT 1),
    1, -- id_planta por defecto
    '2025-12-01',
    '2025-12-01',
    CASE WHEN 'pendiente' = 'reprogramado' THEN 'cancelado' ELSE 'completado' END,
    'pendiente',
    'transferencia'
FROM Sede se
INNER JOIN Empresa e ON se.id_empresa = e.id_empresa
WHERE e.ruc = '20610289321'
AND NOT EXISTS (
    SELECT 1 FROM Servicio s2 
    INNER JOIN Sede se2 ON s2.id_sede = se2.id_sede
    INNER JOIN Empresa e2 ON se2.id_empresa = e2.id_empresa
    WHERE e2.ruc = '20610289321' AND s2.fecha_ejecucion = '2025-12-01'
)
LIMIT 1;


UPDATE Servicio s
INNER JOIN Sede se ON s.id_sede = se.id_sede
INNER JOIN Empresa e ON se.id_empresa = e.id_empresa
SET s.estado_pago = 'pendiente',
    s.forma_pago = 'transferencia',
    s.estado = CASE WHEN 'pendiente' = 'reprogramado' THEN 'cancelado' ELSE 'completado' END,
    s.id_ruta = (SELECT r.id_ruta FROM Ruta r 
                 INNER JOIN Vehiculo v ON r.id_vehiculo = v.id_vehiculo 
                 WHERE r.fecha = '2025-12-01' AND v.modelo = 'DONFENG 1' LIMIT 1)
WHERE e.ruc = '20610289321' AND s.fecha_ejecucion = '2025-12-01';

